@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ───────────────────────── View Transitions ───────────────────────── */

/*
 * The product image carries a per-product `view-transition-name`
 * (`product-image-<slug>`) on both the grid thumbnail and the detail hero.
 * Because the name matches across the old/new snapshots, the browser
 * automatically morphs position and size between them during a navigation —
 * the "shared element" effect. No extra CSS is required for the morph itself.
 */

:root {
  --vt-slide-duration: 0.35s;
}

@keyframes vt-slide-out-left {
  to {
    transform: translateX(-100%);
  }
}

@keyframes vt-slide-in-right {
  from {
    transform: translateX(100%);
  }
}

@keyframes vt-slide-out-right {
  to {
    transform: translateX(100%);
  }
}

@keyframes vt-slide-in-left {
  from {
    transform: translateX(-100%);
  }
}

/* Directional page slides, only when the user is OK with motion. */
@media (prefers-reduced-motion: no-preference) {
  /* Navigating deeper: grid -> product detail. */
  :active-view-transition-type(slide-forward)::view-transition-old(root) {
    animation: vt-slide-out-left var(--vt-slide-duration) ease both;
  }
  :active-view-transition-type(slide-forward)::view-transition-new(root) {
    animation: vt-slide-in-right var(--vt-slide-duration) ease both;
  }

  /* Navigating back: product detail -> grid. */
  :active-view-transition-type(slide-back)::view-transition-old(root) {
    animation: vt-slide-out-right var(--vt-slide-duration) ease both;
  }
  :active-view-transition-type(slide-back)::view-transition-new(root) {
    animation: vt-slide-in-left var(--vt-slide-duration) ease both;
  }
}

/*
 * Respect `prefers-reduced-motion`: collapse every view-transition animation
 * (slides, shared-element morphs, skeleton -> content cross-fades) to an
 * effectively instant swap so no perceptible motion is produced.
 */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-image-pair(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation-duration: 0.01ms !important;
    animation-delay: 0s !important;
  }
}

